/// <summary>
/// CB627_TMSEngineProcessingTOCreation
/// Class responsible for populating the TMS engine TO temp table (calculation table)
/// </summary>
final class METTMSEngineTOLinesTmpBuilder_Pickinglist extends METTMSEngineTOLinesTmpBuilder
{
    WMSPickingRouteID pickingRouteId;
    boolean isInternalCrossDockOrder;
    boolean isCSDWarehouse;
    WMSOrderTrans WMSOrderTrans;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_transferTable">InventTransferTable record</param>
void new(InventTransferTable _transferTable, WMSPickingRouteID _pickingRouteId)
{
    this.init(_transferTable);
    pickingRouteId = _pickingRouteId;
}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_transferLine">Invent Transfer Line</param>
/// <returns>Transfer order quantity</returns>
//protected InventTransferQty lineShipQty(InventTransferLine _transferLine)
//{
//    return _transferLine.QtyTransfer;
//}

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
protected SalesOrderedQty lineShipQty(InventTransferLine   _inventTransferLine)
{

    return EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_inventTransferLine.itemId,
                                                                        _inventTransferLine.InventDimId,
                                                                        WMSOrderTrans.qty,
                                                                        InventTableModule::find(_inventTransferLine.ItemId, ModuleInventPurchSales::Invent).UnitId,
                                                                        InventTable::find(_inventTransferLine.ItemId).salesUnitId(),
                                                                        NoYes::Yes);
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected InventTransferLine getTablesQueryRun(QueryRun _queryRun)
{
    // call the super to get the SalesLine record
    InventTransferLine ret = super(_queryRun);

    // get the WMSOrderTrans record from the queryRun object, specific to PickingList
    WMSOrderTrans = _queryRun.get(tableNum(WMSOrderTrans));

    return ret;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
protected Query initQuery()
{
    Query query = super();
    //If CrossDock or CSD then there might not be a picking list so we don't look at it at all

    // extend the query to add a link to salesOrderShipmentLoadLines so that we can get the new PickedQty instead of salesLine.SalesQty
    QueryBuildDataSource qbds = query.dataSourceTable(tableNum(InventTransferLine));
    QueryBuildDataSource qbdsWMSOrderTrans = qbds.addDataSource(tableNum(WMSOrderTrans));
    qbdsWMSOrderTrans.joinMode(JoinMode::InnerJoin);
    qbdsWMSOrderTrans.addLink(fieldNum(InventTransferLine, InventTransId), fieldNum(WMSOrderTrans, InventTransId));

    // filter shipment lines for the shipment being confirmed
    qbdsWMSOrderTrans.addRange(fieldNum(WMSOrderTrans, routeId)).value(queryValue(pickingRouteId));


    return query;
}
